			}
			return fmt.Errorf("retire source session state: %w", err)
		}
		adopted = next
		filesTouched = touched
		return nil
	})
	if err != nil {
		return nil, nil, fmt.Errorf("adopt external session state: %w", err)
	}
	return adopted, filesTouched, nil
}

